using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using System.Collections.Generic;using System.Reflection;
namespace CircuitoStudio {
internal static class ComponentCsv {
static PropertyInfo[] Properties<T>(string header){return header.Split(';').Select(name=>{var property=typeof(T).GetProperty(name);if(property==null||!property.CanRead||!property.CanWrite)throw new InvalidOperationException("Esquema de tabela inválido.");return property;}).ToArray();}
static object Parse(string text,Type type){var nullable=Nullable.GetUnderlyingType(type);if(nullable!=null){if(String.IsNullOrWhiteSpace(text))return null;return Parse(text,nullable);}if(type==typeof(string))return text;if(type.IsEnum){try{var value=Enum.Parse(type,text,true);if(Enum.IsDefined(type,value))return value;}catch{}throw new InvalidDataException("Enumeração inválida: "+text);}if(type==typeof(double)){double value;if(text.Contains('.')&&text.Contains(','))throw new InvalidDataException("Número ambíguo.");if(!Double.TryParse(text.Trim().Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||Double.IsNaN(value)||Double.IsInfinity(value))throw new InvalidDataException("Número inválido.");return value;}if(type==typeof(int)){int value;if(!Int32.TryParse(text.Trim(),NumberStyles.Integer,CultureInfo.InvariantCulture,out value))throw new InvalidDataException("Inteiro inválido.");return value;}if(type==typeof(bool)){bool value;if(!Boolean.TryParse(text,out value))throw new InvalidDataException("Use true ou false.");return value;}throw new InvalidOperationException("Tipo de coluna não suportado.");}
static void Validate<T>(List<T> rows,Action<T> validate,Func<T,string> key){if(rows.Count>100000)throw new InvalidDataException("Tabela excede 100000 itens.");var keys=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var row in rows){if(Object.ReferenceEquals(row,null))throw new InvalidDataException("Linha ausente.");validate(row);if(!keys.Add(key(row)))throw new InvalidDataException("Condição de componente duplicada.");}}
public static List<T> Import<T>(string file,string header,Action<T> validate,Func<T,string> key) where T:new(){if(new FileInfo(file).Length>32L*1024*1024)throw new InvalidDataException("Arquivo excede 32 MiB.");var rows=CatalogData.Rows(File.ReadAllText(file,Encoding.UTF8).TrimStart('\uFEFF'));if(rows.Count==0||rows.Count>100001||String.Join(";",rows[0])!=header)throw new InvalidDataException("Cabeçalho/tamanho da tabela incompatível.");var properties=Properties<T>(header);var list=new List<T>();for(int i=1;i<rows.Count;i++){try{var cells=rows[i];if(cells.Length!=properties.Length)throw new InvalidDataException("Quantidade de colunas incompatível.");var row=new T();for(int j=0;j<properties.Length;j++)properties[j].SetValue(row,Parse(cells[j],properties[j].PropertyType),null);list.Add(row);}catch(Exception ex){throw new InvalidDataException("Registro "+(i+1)+": "+ex.Message,ex);}}Validate(list,validate,key);return list;}
static string Quote(string value){return "\""+value.Replace("\"","\"\"")+"\"";}
public static void Export<T>(IEnumerable<T> source,string file,string header,Action<T> validate,Func<T,string> key){var list=source.ToList();Validate(list,validate,key);var properties=Properties<T>(header);string full=Path.GetFullPath(file);Directory.CreateDirectory(Path.GetDirectoryName(full));string temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{long bytes=3+Encoding.UTF8.GetByteCount(header+"\r\n");using(var w=new StreamWriter(temp,false,new UTF8Encoding(true))){w.WriteLine(header);foreach(var row in list){string line=String.Join(";",properties.Select(property=>{object value=property.GetValue(row,null);return Quote(value is double?((double)value).ToString("R",CultureInfo.InvariantCulture):Convert.ToString(value,CultureInfo.InvariantCulture)??"");}));bytes+=Encoding.UTF8.GetByteCount(line+"\r\n");if(bytes>32L*1024*1024)throw new InvalidDataException("Tabela excede 32 MiB; destino preservado.");w.WriteLine(line);}}if(File.Exists(full))File.Replace(temp,full,full+".bak");else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
}
